  panel.slider(c, 'aim lead', 0, 0.5, 0.01, () => cam.aimLead, v => { cam.aimLead = v; });

  // ================================================================ DIRECT LIGHT: the estimator (ReSTIR / leader-tail), shadow rays + the penumbra filter, character shadows, the lossless culls, the lossy trades, the level's lights
  panel.system(SYS.direct);
  const restirLine = () => S.restir ? `restir: ${S.restirRays} rays · k ${S.restirSpatial} · M ≤ ${S.restirHistory} · reservoirs ${(engine.passes.restirBytes / 1048576).toFixed(0)} MB · ${engine.lights.activeCount} lights (${engine.lights.prevCount} last frame)` : 'restir: off — leader / tail estimator (direct.wgsl)';
  const dl = panel.section('Estimator — ReSTIR DI', { open: true, summary: restirLine });
  flag(dl, 'enabled', FrameFlags.Direct, 'sampled ray-traced direct light: every light scored per pixel, the strongest per emitter class get shadow rays to points on their emitters');
  panel.toggleBox(dl, 'ReSTIR DI (v3 Phase 2a)', () => S.restir, v => { S.restir = v; }, 'the direct-light ESTIMATOR. On: ReSTIR DI (render/shaders/restir.wgsl) — every light the tile can see is still scored unshadowed per pixel (that is U, exact, and the candidate pdf), but instead of K leaders × stratified rays + a tail ray each pixel keeps ONE reservoir per emitter class (a light + a point on its emitter, with an unbiased contribution weight), re-traces it, draws a fresh candidate ∝ its unshadowed light, MIS-combines them against last frame\'s light list (a light new this frame enters at full weight — flashes light instantly), taps its neighbours\' reservoirs, and shades S = U × the estimated visible fraction: a FIXED shadow-ray budget per pixel however many lights are on. Off (?norestir): direct.wgsl\'s leader / tail estimator exactly as it was. Same four outputs, same penumbra filter after it');
  panel.slider(dl, 'restir: HYBRID — held-light rays K (0 = off)', 0, 8, 1, () => S.heldRays, v => { S.heldRays = v; }, 'THE HYBRID ESTIMATOR: every light a character CARRIES (owner byte ≠ 0: the guards\' torches, the player\'s rail / gun light, muzzle flashes, tracer heads) bypasses the reservoirs at the pixels it reaches and gets the old leader treatment every frame — the two strongest at the pixel take K stratified emitter samples each, shaded exactly, any further ones one tail ray a class; static lights (owner 0) keep ReSTIR. A carried light moves every frame, so its reservoir history and the shadow client\'s ratio history are let go wherever the cone sweeps and the pool was shaded from one or two fresh rays: noisy pools, ragged edges, rims. The presets tier K (ultra 8 · high 4 · medium 4 · low 3 · verylow 2); 0 = off, the transient stratum exactly as it was (docs/internal/direct-quality.md)');
  // THE LIGHTING TRADES (restir.wgsl TRADES): rows that give up a little accuracy for shadow rays — all OFF by default (off = the estimator as it was); for pricing on a real GPU
  panel.toggleBox(dl, 'TRADE: held rays stop at 2 if agreed', () => S.heldAdaptive, v => { S.heldAdaptive = v; }, 'a carried light\'s first two stratified rays that agree (both lit, both blocked) stand for all K: 2 rays instead of K inside the cone and behind walls, the full K where they differ. Cost: its wide penumbrae harden a little and grain more (a pixel 90 % lit reads about 94 %), and an occluder thinner than the lens spread can be missed by both rays. Needs K above 2.');
  panel.toggleBox(dl, 'TRADE: settled pixels re-trace 1 in 2', () => S.restirStableRetrace, v => { S.restirStableRetrace = v; }, 'a reservoir sample that is fully lit, with most of its memory and no penumbra measured at the pixel last frame, is re-traced on alternate frames only (the fresh candidates still look every frame). Cost: a shadow arriving on a settled lit pixel can show a frame late along its leading edge.');
  panel.slider(dl, 'TRADE: dim class', 0, 0.5, 0.01, () => S.restirDimClass, v => { S.restirDimClass = v; }, 'share of the pixel\'s light; 0 = off. An emitter class (sharp / broad) under this share of the pixel\'s live unshadowed light takes one shadow ray a frame (re-trace and fresh alternate) and no second penumbra ray. Cost: grain in that class, worst where the bright class is itself in shadow. Try 0.05.');
