    panel.toggleBox(ws, 'walls ▸ partitions and cover break', () => WT.wallBreak !== false, (v: boolean) => { WT.wallBreak = v; game.msg(`walls and cover ${v ? 'break under fire and blasts' : 'only scar'}`); },
      'interior partition walls are holed by a charge and ported by sustained fire, and cover is chewed away — picture, rounds, eyes, sound, feet and the nav grid all take the same change. Off = what is already broken stays broken until a restart; nothing new breaks. Not kept per machine. The whole destruction goal goes off with ?nodestruction');
    panel.toggleBox(ws, 'wall charge ▸ goes on outer walls', () => WALLCHARGE.outer, (v: boolean) => { WALLCHARGE.outer = v; game.msg(`a wall charge ${v ? 'goes on a building\'s outer wall too' : 'is refused on outer walls, as it was'}`); },
      `a building's outer wall (structure up to ${WALLCHARGE.outerThick} m, not steel, the open sky over one face) takes a wall charge by the partition\'s own presses — X, 5, 3 for the squad, the Space row for you, F blows it — and the charge opens a way in a metre and a half wide. Only the charge set on it opens it: rounds, grenades and other blasts still only scar it. Off = outer walls are refused in words, as before (the page\'s ?noouterwall). Not kept per machine`);
    panel.toggleBox(ws, 'wall charge ▸ larger safety radius', () => WALLCHARGE.safe, (v: boolean) => { WALLCHARGE.safe = v; game.msg(`the wall charge's safety radius is ${v ? 'the larger one — larger again indoors' : 'as it was'}`); },
      `the squad stands off ${WALLCHARGE.safeStandoff[0]} m from a wall charge outdoors and ${WALLCHARGE.safeStandoff[1]} m indoors (or out of its line: round a corner, out of the room), and on its own side the blast reaches ${WALLCHARGE.safeReach[0]} m outdoors and ${WALLCHARGE.safeReach[1]} m indoors: a teammate inside it is blinded, you are rocked — no round for a beat, your aim wide. The trigger's row names who is too close. Off = 2.6 m and 1.6 m, as it was.`);
    panel.toggleBox(ws, 'wall charge ▸ stand off out of known fire', () => WALLCHARGE.outOfFire, (v: boolean) => { WALLCHARGE.outOfFire = v; game.msg(`the squad stands off a wall charge ${v ? 'out of the fire of enemies it knows of, where the floor lets it' : 'on the nearest safe marks, whatever looks at them'}`); },
      'also ?standfire=0 on the address. With the larger safety radius on: of the places out of the blast, the men take the ones no enemy the team knows of can shoot first (in the picture now, or seen in the last half minute where he was last seen; with each man\'s own picture on, a man one of them heard or was told of in that time too), then the least exposed. No new place is looked for: where all the safe floor is watched they still stand on it. Off = the nearest safe marks, as it was. Not kept per machine');
    panel.toggleBox(ws, 'wall charge ▸ men with you step back', () => WALLCHARGE.menClear, (v: boolean) => { WALLCHARGE.menClear = v; game.msg(`the men with you ${v ? 'step back from a charge set on a wall' : 'keep their places in the file by a set wall charge'}`); },
      'also ?menclear=0 on the address. With the larger safety radius on: a man on fall in whose place is in the line of a charge on a wall and nearer than its stand-off distance walks to a stand-off mark (along the wall past the radius, out of its line, or back across the floor; only on floor the squad holds) and keeps it until his place is clear — you walking away with the file behind you, or the charge gone. Never a sprint. A man on an order of his own keeps it. Off = they keep their places, as it was. Not kept per machine');
    panel.toggleBox(ws, 'wall charge ▸ yard walls too', () => WALLCHARGE.outerYard, (v: boolean) => { WALLCHARGE.outerYard = v; game.msg(`a wall charge ${v ? 'goes on yard walls too' : 'goes on a building\'s own outer walls only'}`); }, 'with the row above on: a free-standing yard or perimeter wall (the sky over both faces) takes the charge as well. Off = only walls with a roof behind one face. Not kept per machine');
    panel.slider(ws, 'wall charge ▸ camera kick', 0, 2, 0.1, () => feelKick(), (v: number) => { FEEL.kick = v; saveFeel(); }, 'how hard a wall charge going off throws the picture (game/blastFeel.ts): 1 = as authored — a snap away from the blast of up to a quarter of a metre at the wall, rung down inside half a second, less with distance; 0 = none (motion comfort). Picture only: the aim, the controls and the game read the camera without it. Kept on this machine.');
    panel.buttons(ws, 'walls', [
      { text: 'charge at cursor', run: () => { const a = game.aimPoint; const r = game.destr.blast([a[0], Math.max(a[1], 0.3), a[2]], DESTRUCTION.on ? {} : { chaos: false }); game.msg(`charge: ${r.walls} wall${r.walls === 1 ? '' : 's'} holed, ${r.cover} cover, ${r.opened} floor cells opened`); }, title: 'test: the one blast entry point (game.destr.blast) where the cursor is, on the floor — no flash, nobody hurt, no noise: put it against a partition to open a hole a man fits through' }]);
